im=np.asarray(Image.open('images/fig_055.png').convert('RGB')).astype(int)
# Look at pixel colors at a known marker. Red triangle at px (298,285)?
# Print a small box around a plateau marker
def box(cx,cy,n=5):
    print('box around',cx,cy)
    for y in range(cy-n,cy+n+1):
        row=[]
        for x in range(cx-n,cx+n+1):
