import numpy as np
from PIL import Image
a=np.asarray(Image.open('images/fig_055.png').convert('RGB')).astype(int)
mx=a.max(axis=2); mn=a.min(axis=2)
dark=(mx<200).astype(float)  # darkness channel
def ncc(img, tmpl, x, y):
    # img[y,y+h][x,x+w] vs tmpl
    h,w=tmpl.shape
    patch=img[y:y+h,x:x+w]
    p=patch-patch.mean(); t=tmpl-tmpl.mean()
    denom=np.sqrt((p*p).sum()*(t*t).sum())
    if denom<1e-6: return -1
    return float((p*t).sum()/denom)
# templates: square ring of size s (outer), from observed shape: ring thickness 1-2 px
def square_tmpl(s, thick=2):
    t=np.zeros((s,s))
    for i in range(s):
        for j in range(s):
            d=min(i,j,s-1-i,s-1-j)
            t[i,j]=1 if d<thick else 0
    return t
tg=255-a.min(axis=2)  # ink
for s in (7,8,9,10):
    t=square_tmpl(s)
    best=[]
    for y in range(35,470):
        for x in range(118,700):
            v=ncc(tg,t,x,y)
            if v>0.55: best.append((v,x,y))
    best.sort(reverse=True)
    # non-max suppression 4px
    keep=[]
    for v,x,y in best:
        if all((x-kx)**2+(y-ky)**2>16 for _,kx,ky in keep): keep.append((v,x,y))
    print('s=%d n=%d'%(s,len(keep)))
    if s==9:
        keep.sort(key=lambda t:(t[1],t[2]))
        print(keep[:80])
